    false, 'General Tamil & General Studies', 'TNPSC', 'Phase 1: High Weightage Foundation', 'அலகு I: எழுத்து (பிரித்து/சேர்த்து எழுதுதல், சந்திப்பிழை, குறில்/நெடில், ல/ள/ழ வேறுபாடு) | சுருக்குதல் ',
    'அலகு I: எழுத்து (பிரித்து/சேர்த்து எழுதுதல், சந்திப்பிழை, குறில்/நெடில், ல/ள/ழ வேறுபாடு)', 'TNPSC-G2-D01', 135, 150,
    '[{"id":"vid_tnpsc_g2_d1_1","title":"TNPSC General Tamil Day 1 Masterclass","tamilTitle":"பொதுத்தமிழ் நாள் 1 முழு விளக்கம்","youtubeVideoId":"EpdTHQ0s6oM","channelName":"@aishleetechnology","durationMinutes":25,"type":"foundation","summary":"அலகு I: எழுத்து (பிரித்து/சேர்த்து எழுதுதல், சந்திப்பிழை, குறில்/நெடில், ல/ள/ழ வேறுபாடு)"},{"id":"vid_tnpsc_g2_d1_2","title":"TNPSC Aptitude 25/25 Day 1 Speed Shortcuts","tamilTitle":"கணிதம் & திறனறிவு நாள் 1 குறுக்குவழிகள்","youtubeVideoId":"aishlee_tnpsc_aptitude_1","channelName":"@aishleetechnology","durationMinutes":20,"type":"derivation","summary":"சுருக்குதல் (Simplification - BODMAS, வர்க்க/கன மூலம்)"},{"id":"vid_tnpsc_g2_d1_3","title":"TNPSC General Studies Day 1 High-Scoring Topics","tamilTitle":"பொது அறிவு நாள் 1 முக்கிய வினாக்கள்","youtubeVideoId":"0TgLtF3PMOc","channelName":"@aishleetechnology","durationMinutes":20,"type":"pyq","summary":"Unit 8: தொல்லியல் கண்டுபிடிப்புகள் (கீழடி, ஆதிச்சநல்லூர்) & Polity: முகவுரை, முக்கிய கூறுகள்"}]'::jsonb, '[{"id":"note_tnpsc_g2_d1_admin","title":"TNPSC Group 2 Core High-Yield Deck (Day 1)","tamilTitle":"பாடக் குறிப்புகள் மற்றும் முக்கிய வினாக்கள்","type":"admin_core_ai","content":"Official Syllabus Review for Day 1. Tamil: அலகு I: எழுத்து (பிரித்து/சேர்த்து எழுதுதல், சந்திப்பிழை, குறில்/நெடில், ல/ள/ழ வேறுபாடு). Maths: சுருக்குதல் (Simplification - BODMAS, வர்க்க/கன மூலம்). GS: Unit 8: தொல்லியல் கண்டுபிடிப்புகள் (கீழடி, ஆதிச்சநல்லூர்) & Polity: முகவுரை, முக்கிய கூறுகள்.","formulasOrKeyRules":["TNPSC Target 185+ / 200 Questions","Zero Negative Marking Advantage","Daily Active Recall Active"],"examTrapsToAvoid":["Carefully check \"பொருந்தாதது எது\"","Do not misread similar Tamil words","Avoid calculation slips in algebra"]},{"id":"note_tnpsc_g2_d1_exam","title":"Day 1 Exam Tips & Memory Flashcards","tamilTitle":"நினைவுப் பலகைகள் மற்றும் குறுக்குவழி அட்டவணை","type":"admin_exam_ai","content":"Detailed memory aids and chronological timelines for Day 1.","formulasOrKeyRules":["5-Minute active recall every 45 mins","Night error log remediation"]}]'::jsonb, '{"testId":"test_tnpsc_g2_d1","title":"TNPSC Group 2 Daily Speed CBT Drill (Day 1)","tamilTitle":"நாள் 1 இணையவழி மாதிரித் தேர்வு (25 வினாக்கள்)","totalQuestions":25,"durationMinutes":25,"passingScore":20,"questions":[{"id":"q_g2_d1_1","question":"Sample Assessment for Day 1: Master Question 1 covering Tamil and GS.","questionTamil":"நாள் 1 பாடப்பகுதி மாதிரி வினா 1: பாடத்திட்ட அடிப்படையிலான தேர்வு.","options":{"A":"Option A (சரியான விடை)","B":"Option B","C":"Option C","D":"Option D"},"correctOption":"A","explanation":"Detailed explanation based on TNPSC syllabus standard."}]}'::jsonb, '{"asanaName":"Surya Namaskar & Nadi Shodhana Pranayama","tamilName":"சூரிய நமஸ்காரம் & நாடி சுத்தி பிராணாயாமம்","durationMinutes":15,"benefits":"Enhances neuro-cerebral oxygenation, sharpens memory retention and calms exam anxiety.","brainBoosterTask":"Solve 10 mental math calculation sprints without paper or pen in under 3 minutes."}'::jsonb
) ON CONFLICT (course_id, day_number) DO UPDATE SET
