    '[{"id":"vid_tnpsc_g2_d3_1","title":"TNPSC General Tamil Day 3 Masterclass","tamilTitle":"பொதுத்தமிழ் நாள் 3 முழு விளக்கம்","youtubeVideoId":"EpdTHQ0s6oM","channelName":"@aishleetechnology","durationMinutes":25,"type":"foundation","summary":"அலகு I: சொல் (வேர்ச்சொல், வினைமுற்று, வினையெச்சம்) & அலகு VII: திருக்குறள் (ஒழுக்கமுடைமை, பொறையுடைமை, ஊக்கமுடைமை)"},{"id":"vid_tnpsc_g2_d3_2","title":"TNPSC Aptitude 25/25 Day 3 Speed Shortcuts","tamilTitle":"கணிதம் & திறனறிவு நாள் 3 குறுக்குவழிகள்","youtubeVideoId":"aishlee_tnpsc_aptitude_1","channelName":"@aishleetechnology","durationMinutes":20,"type":"derivation","summary":"மீப்பெரு பொதுக் காரணி (HCF) & மீச்சிறு பொது மடங்கு (LCM)"},{"id":"vid_tnpsc_g2_d3_3","title":"TNPSC General Studies Day 3 High-Scoring Topics","tamilTitle":"பொது அறிவு நாள் 3 முக்கிய வினாக்கள்","youtubeVideoId":"0TgLtF3PMOc","channelName":"@aishleetechnology","durationMinutes":20,"type":"pyq","summary":"Unit 8: திருக்குறள் மதச்சார்பற்ற இலக்கியம் & Polity: அடிப்படைக் கடமைகள், அரசு நெறிமுறைக் கோட்பாடுகள்"}]'::jsonb, '[{"id":"note_tnpsc_g2_d3_admin","title":"TNPSC Group 2 Core High-Yield Deck (Day 3)","tamilTitle":"பாடக் குறிப்புகள் மற்றும் முக்கிய வினாக்கள்","type":"admin_core_ai","content":"Official Syllabus Review for Day 3. Tamil: அலகு I: சொல் (வேர்ச்சொல், வினைமுற்று, வினையெச்சம்) & அலகு VII: திருக்குறள் (ஒழுக்கமுடைமை, பொறையுடைமை, ஊக்கமுடைமை). Maths: மீப்பெரு பொதுக் காரணி (HCF) & மீச்சிறு பொது மடங்கு (LCM). GS: Unit 8: திருக்குறள் மதச்சார்பற்ற இலக்கியம் & Polity: அடிப்படைக் கடமைகள், அரசு நெறிமுறைக் கோட்பாடுகள்.","formulasOrKeyRules":["TNPSC Target 185+ / 200 Questions","Zero Negative Marking Advantage","Daily Active Recall Active"],"examTrapsToAvoid":["Carefully check \"பொருந்தாதது எது\"","Do not misread similar Tamil words","Avoid calculation slips in algebra"]},{"id":"note_tnpsc_g2_d3_exam","title":"Day 3 Exam Tips & Memory Flashcards","tamilTitle":"நினைவுப் பலகைகள் மற்றும் குறுக்குவழி அட்டவணை","type":"admin_exam_ai","content":"Detailed memory aids and chronological timelines for Day 3.","formulasOrKeyRules":["5-Minute active recall every 45 mins","Night error log remediation"]}]'::jsonb, '{"testId":"test_tnpsc_g2_d3","title":"TNPSC Group 2 Daily Speed CBT Drill (Day 3)","tamilTitle":"நாள் 3 இணையவழி மாதிரித் தேர்வு (25 வினாக்கள்)","totalQuestions":25,"durationMinutes":25,"passingScore":20,"questions":[{"id":"q_g2_d3_1","question":"Sample Assessment for Day 3: Master Question 1 covering Tamil and GS.","questionTamil":"நாள் 3 பாடப்பகுதி மாதிரி வினா 1: பாடத்திட்ட அடிப்படையிலான தேர்வு.","options":{"A":"Option A (சரியான விடை)","B":"Option B","C":"Option C","D":"Option D"},"correctOption":"A","explanation":"Detailed explanation based on TNPSC syllabus standard."}]}'::jsonb, '{"asanaName":"Surya Namaskar & Nadi Shodhana Pranayama","tamilName":"சூரிய நமஸ்காரம் & நாடி சுத்தி பிராணாயாமம்","durationMinutes":15,"benefits":"Enhances neuro-cerebral oxygenation, sharpens memory retention and calms exam anxiety.","brainBoosterTask":"Solve 10 mental math calculation sprints without paper or pen in under 3 minutes."}'::jsonb
