    false, 'General Tamil & General Studies', 'TNPSC', 'Phase 1: High Weightage Foundation', 'அலகு I: சொல் (அயற்சொல்-தமிழ்ச்சொல், எதிர்ச்சொல், ஒற்றுப்பிழை)  | விகிதம் மற்றும் விகிதாச்சாரம் ',
    'அலகு I: சொல் (அயற்சொல்-தமிழ்ச்சொல், எதிர்ச்சொல், ஒற்றுப்பிழை) & அலகு VII: திருக்குறள் (விருந்தோம்பல், அறன்வலியுறுத்தல், ஈகை)', 'TNPSC-G2-D04', 135, 150,
    '[{"id":"vid_tnpsc_g2_d4_1","title":"TNPSC General Tamil Day 4 Masterclass","tamilTitle":"பொதுத்தமிழ் நாள் 4 முழு விளக்கம்","youtubeVideoId":"EpdTHQ0s6oM","channelName":"@aishleetechnology","durationMinutes":25,"type":"foundation","summary":"அலகு I: சொல் (அயற்சொல்-தமிழ்ச்சொல், எதிர்ச்சொல், ஒற்றுப்பிழை) & அலகு VII: திருக்குறள் (விருந்தோம்பல், அறன்வலியுறுத்தல், ஈகை)"},{"id":"vid_tnpsc_g2_d4_2","title":"TNPSC Aptitude 25/25 Day 4 Speed Shortcuts","tamilTitle":"கணிதம் & திறனறிவு நாள் 4 குறுக்குவழிகள்","youtubeVideoId":"aishlee_tnpsc_aptitude_1","channelName":"@aishleetechnology","durationMinutes":20,"type":"derivation","summary":"விகிதம் மற்றும் விகிதாச்சாரம் (Ratio & Proportion)"},{"id":"vid_tnpsc_g2_d4_3","title":"TNPSC General Studies Day 4 High-Scoring Topics","tamilTitle":"பொது அறிவு நாள் 4 முக்கிய வினாக்கள்","youtubeVideoId":"0TgLtF3PMOc","channelName":"@aishleetechnology","durationMinutes":20,"type":"pyq","summary":"Unit 8: திருக்குறள் மானுட தாக்கம் & Polity: ஒன்றிய நிர்வாகம் (குடியரசுத் தலைவர், பிரதமர்)"}]'::jsonb, '[{"id":"note_tnpsc_g2_d4_admin","title":"TNPSC Group 2 Core High-Yield Deck (Day 4)","tamilTitle":"பாடக் குறிப்புகள் மற்றும் முக்கிய வினாக்கள்","type":"admin_core_ai","content":"Official Syllabus Review for Day 4. Tamil: அலகு I: சொல் (அயற்சொல்-தமிழ்ச்சொல், எதிர்ச்சொல், ஒற்றுப்பிழை) & அலகு VII: திருக்குறள் (விருந்தோம்பல், அறன்வலியுறுத்தல், ஈகை). Maths: விகிதம் மற்றும் விகிதாச்சாரம் (Ratio & Proportion). GS: Unit 8: திருக்குறள் மானுட தாக்கம் & Polity: ஒன்றிய நிர்வாகம் (குடியரசுத் தலைவர், பிரதமர்).","formulasOrKeyRules":["TNPSC Target 185+ / 200 Questions","Zero Negative Marking Advantage","Daily Active Recall Active"],"examTrapsToAvoid":["Carefully check \"பொருந்தாதது எது\"","Do not misread similar Tamil words","Avoid calculation slips in algebra"]},{"id":"note_tnpsc_g2_d4_exam","title":"Day 4 Exam Tips & Memory Flashcards","tamilTitle":"நினைவுப் பலகைகள் மற்றும் குறுக்குவழி அட்டவணை","type":"admin_exam_ai","content":"Detailed memory aids and chronological timelines for Day 4.","formulasOrKeyRules":["5-Minute active recall every 45 mins","Night error log remediation"]}]'::jsonb, '{"testId":"test_tnpsc_g2_d4","title":"TNPSC Group 2 Daily Speed CBT Drill (Day 4)","tamilTitle":"நாள் 4 இணையவழி மாதிரித் தேர்வு (25 வினாக்கள்)","totalQuestions":25,"durationMinutes":25,"passingScore":20,"questions":[{"id":"q_g2_d4_1","question":"Sample Assessment for Day 4: Master Question 1 covering Tamil and GS.","questionTamil":"நாள் 4 பாடப்பகுதி மாதிரி வினா 1: பாடத்திட்ட அடிப்படையிலான தேர்வு.","options":{"A":"Option A (சரியான விடை)","B":"Option B","C":"Option C","D":"Option D"},"correctOption":"A","explanation":"Detailed explanation based on TNPSC syllabus standard."}]}'::jsonb, '{"asanaName":"Surya Namaskar & Nadi Shodhana Pranayama","tamilName":"சூரிய நமஸ்காரம் & நாடி சுத்தி பிராணாயாமம்","durationMinutes":15,"benefits":"Enhances neuro-cerebral oxygenation, sharpens memory retention and calms exam anxiety.","brainBoosterTask":"Solve 10 mental math calculation sprints without paper or pen in under 3 minutes."}'::jsonb
