    '[{"id":"vid_tnpsc_g2_d11_1","title":"TNPSC General Tamil Day 11 Masterclass","tamilTitle":"பொதுத்தமிழ் நாள் 11 முழு விளக்கம்","youtubeVideoId":"EpdTHQ0s6oM","channelName":"@aishleetechnology","durationMinutes":25,"type":"foundation","summary":"அலகு VII: அறநூல்கள் (முதுமொழிக்காஞ்சி, திரிகடுகம், இன்னாநாற்பது) & அலகு II: பிழை திருத்துக (ஒரு-ஓர், வெத்தில-வெற்றிலை)"},{"id":"vid_tnpsc_g2_d11_2","title":"TNPSC Aptitude 25/25 Day 11 Speed Shortcuts","tamilTitle":"கணிதம் & திறனறிவு நாள் 11 குறுக்குவழிகள்","youtubeVideoId":"aishlee_tnpsc_aptitude_1","channelName":"@aishleetechnology","durationMinutes":20,"type":"derivation","summary":"புதிர்கள் (Puzzles, இருக்கை அமைப்பு, இரத்த உறவுகள்)"},{"id":"vid_tnpsc_g2_d11_3","title":"TNPSC General Studies Day 11 High-Scoring Topics","tamilTitle":"பொது அறிவு நாள் 11 முக்கிய வினாக்கள்","youtubeVideoId":"0TgLtF3PMOc","channelName":"@aishleetechnology","durationMinutes":20,"type":"pyq","summary":"Unit 8: சுயமரியாதை இயக்கம் 1925, பெரியார் பங்களிப்புகள் & Polity: பெண்கள் அதிகாரமளித்தல், நுகர்வோர் பாதுகாப்பு"}]'::jsonb, '[{"id":"note_tnpsc_g2_d11_admin","title":"TNPSC Group 2 Core High-Yield Deck (Day 11)","tamilTitle":"பாடக் குறிப்புகள் மற்றும் முக்கிய வினாக்கள்","type":"admin_core_ai","content":"Official Syllabus Review for Day 11. Tamil: அலகு VII: அறநூல்கள் (முதுமொழிக்காஞ்சி, திரிகடுகம், இன்னாநாற்பது) & அலகு II: பிழை திருத்துக (ஒரு-ஓர், வெத்தில-வெற்றிலை). Maths: புதிர்கள் (Puzzles, இருக்கை அமைப்பு, இரத்த உறவுகள்). GS: Unit 8: சுயமரியாதை இயக்கம் 1925, பெரியார் பங்களிப்புகள் & Polity: பெண்கள் அதிகாரமளித்தல், நுகர்வோர் பாதுகாப்பு.","formulasOrKeyRules":["TNPSC Target 185+ / 200 Questions","Zero Negative Marking Advantage","Daily Active Recall Active"],"examTrapsToAvoid":["Carefully check \"பொருந்தாதது எது\"","Do not misread similar Tamil words","Avoid calculation slips in algebra"]},{"id":"note_tnpsc_g2_d11_exam","title":"Day 11 Exam Tips & Memory Flashcards","tamilTitle":"நினைவுப் பலகைகள் மற்றும் குறுக்குவழி அட்டவணை","type":"admin_exam_ai","content":"Detailed memory aids and chronological timelines for Day 11.","formulasOrKeyRules":["5-Minute active recall every 45 mins","Night error log remediation"]}]'::jsonb, '{"testId":"test_tnpsc_g2_d11","title":"TNPSC Group 2 Daily Speed CBT Drill (Day 11)","tamilTitle":"நாள் 11 இணையவழி மாதிரித் தேர்வு (25 வினாக்கள்)","totalQuestions":25,"durationMinutes":25,"passingScore":20,"questions":[{"id":"q_g2_d11_1","question":"Sample Assessment for Day 11: Master Question 1 covering Tamil and GS.","questionTamil":"நாள் 11 பாடப்பகுதி மாதிரி வினா 1: பாடத்திட்ட அடிப்படையிலான தேர்வு.","options":{"A":"Option A (சரியான விடை)","B":"Option B","C":"Option C","D":"Option D"},"correctOption":"A","explanation":"Detailed explanation based on TNPSC syllabus standard."}]}'::jsonb, '{"asanaName":"Surya Namaskar & Nadi Shodhana Pranayama","tamilName":"சூரிய நமஸ்காரம் & நாடி சுத்தி பிராணாயாமம்","durationMinutes":15,"benefits":"Enhances neuro-cerebral oxygenation, sharpens memory retention and calms exam anxiety.","brainBoosterTask":"Solve 10 mental math calculation sprints without paper or pen in under 3 minutes."}'::jsonb
