    false, 'General Tamil & General Studies', 'TNPSC', 'Phase 2: Core Scoring Surge', 'அலகு VII: தமிழின் தொன்மை, உ.வே.சா, தெ.பொ.மீ, சி.இலக்குவனார்  | காட்சிக் காரணவியல் ',
    'அலகு VII: தமிழின் தொன்மை, உ.வே.சா, தெ.பொ.மீ, சி.இலக்குவனார் & அலகு II: சொற்களை இணைத்துப் புதிய சொல்', 'TNPSC-G2-D13', 135, 150,
    '[{"id":"vid_tnpsc_g2_d13_1","title":"TNPSC General Tamil Day 13 Masterclass","tamilTitle":"பொதுத்தமிழ் நாள் 13 முழு விளக்கம்","youtubeVideoId":"EpdTHQ0s6oM","channelName":"@aishleetechnology","durationMinutes":25,"type":"foundation","summary":"அலகு VII: தமிழின் தொன்மை, உ.வே.சா, தெ.பொ.மீ, சி.இலக்குவனார் & அலகு II: சொற்களை இணைத்துப் புதிய சொல்"},{"id":"vid_tnpsc_g2_d13_2","title":"TNPSC Aptitude 25/25 Day 13 Speed Shortcuts","tamilTitle":"கணிதம் & திறனறிவு நாள் 13 குறுக்குவழிகள்","youtubeVideoId":"aishlee_tnpsc_aptitude_1","channelName":"@aishleetechnology","durationMinutes":20,"type":"derivation","summary":"காட்சிக் காரணவியல் (Visual Reasoning, கண்ணாடி பிம்பம், உருவங்கள் எண்ணுதல்)"},{"id":"vid_tnpsc_g2_d13_3","title":"TNPSC General Studies Day 13 High-Scoring Topics","tamilTitle":"பொது அறிவு நாள் 13 முக்கிய வினாக்கள்","youtubeVideoId":"0TgLtF3PMOc","channelName":"@aishleetechnology","durationMinutes":20,"type":"pyq","summary":"Unit 9: ஐந்தாண்டு திட்டங்கள், திட்டக்குழு & நிதி ஆயோக், RBI பணவியல் கொள்கை, Finance Commission"}]'::jsonb, '[{"id":"note_tnpsc_g2_d13_admin","title":"TNPSC Group 2 Core High-Yield Deck (Day 13)","tamilTitle":"பாடக் குறிப்புகள் மற்றும் முக்கிய வினாக்கள்","type":"admin_core_ai","content":"Official Syllabus Review for Day 13. Tamil: அலகு VII: தமிழின் தொன்மை, உ.வே.சா, தெ.பொ.மீ, சி.இலக்குவனார் & அலகு II: சொற்களை இணைத்துப் புதிய சொல். Maths: காட்சிக் காரணவியல் (Visual Reasoning, கண்ணாடி பிம்பம், உருவங்கள் எண்ணுதல்). GS: Unit 9: ஐந்தாண்டு திட்டங்கள், திட்டக்குழு & நிதி ஆயோக், RBI பணவியல் கொள்கை, Finance Commission.","formulasOrKeyRules":["TNPSC Target 185+ / 200 Questions","Zero Negative Marking Advantage","Daily Active Recall Active"],"examTrapsToAvoid":["Carefully check \"பொருந்தாதது எது\"","Do not misread similar Tamil words","Avoid calculation slips in algebra"]},{"id":"note_tnpsc_g2_d13_exam","title":"Day 13 Exam Tips & Memory Flashcards","tamilTitle":"நினைவுப் பலகைகள் மற்றும் குறுக்குவழி அட்டவணை","type":"admin_exam_ai","content":"Detailed memory aids and chronological timelines for Day 13.","formulasOrKeyRules":["5-Minute active recall every 45 mins","Night error log remediation"]}]'::jsonb, '{"testId":"test_tnpsc_g2_d13","title":"TNPSC Group 2 Daily Speed CBT Drill (Day 13)","tamilTitle":"நாள் 13 இணையவழி மாதிரித் தேர்வு (25 வினாக்கள்)","totalQuestions":25,"durationMinutes":25,"passingScore":20,"questions":[{"id":"q_g2_d13_1","question":"Sample Assessment for Day 13: Master Question 1 covering Tamil and GS.","questionTamil":"நாள் 13 பாடப்பகுதி மாதிரி வினா 1: பாடத்திட்ட அடிப்படையிலான தேர்வு.","options":{"A":"Option A (சரியான விடை)","B":"Option B","C":"Option C","D":"Option D"},"correctOption":"A","explanation":"Detailed explanation based on TNPSC syllabus standard."}]}'::jsonb, '{"asanaName":"Surya Namaskar & Nadi Shodhana Pranayama","tamilName":"சூரிய நமஸ்காரம் & நாடி சுத்தி பிராணாயாமம்","durationMinutes":15,"benefits":"Enhances neuro-cerebral oxygenation, sharpens memory retention and calms exam anxiety.","brainBoosterTask":"Solve 10 mental math calculation sprints without paper or pen in under 3 minutes."}'::jsonb
