) VALUES (
    'tnpsc-group2', 'TNPSC Group 2 & 2A — 25-Day Centum Ranker Fast-Track', 15, 3, 'Day 15',
    false, 'General Tamil & General Studies', 'TNPSC', 'Phase 2: Core Scoring Surge', 'அலகு VII: தமிழ்ச் சான்றோர் (பாரதிதாசன், டி.கே.சி, குன்றக்குடி, கண்ணதாசன், காயிதே மில்லத்)  | எண் வரிசை ',
    'அலகு VII: தமிழ்ச் சான்றோர் (பாரதிதாசன், டி.கே.சி, குன்றக்குடி, கண்ணதாசன், காயிதே மில்லத்) & பொருள் தரும் ஓரெழுத்து', 'TNPSC-G2-D15', 135, 150,
    '[{"id":"vid_tnpsc_g2_d15_1","title":"TNPSC General Tamil Day 15 Masterclass","tamilTitle":"பொதுத்தமிழ் நாள் 15 முழு விளக்கம்","youtubeVideoId":"EpdTHQ0s6oM","channelName":"@aishleetechnology","durationMinutes":25,"type":"foundation","summary":"அலகு VII: தமிழ்ச் சான்றோர் (பாரதிதாசன், டி.கே.சி, குன்றக்குடி, கண்ணதாசன், காயிதே மில்லத்) & பொருள் தரும் ஓரெழுத்து"},{"id":"vid_tnpsc_g2_d15_2","title":"TNPSC Aptitude 25/25 Day 15 Speed Shortcuts","tamilTitle":"கணிதம் & திறனறிவு நாள் 15 குறுக்குவழிகள்","youtubeVideoId":"aishlee_tnpsc_aptitude_1","channelName":"@aishleetechnology","durationMinutes":20,"type":"derivation","summary":"எண் வரிசை (Number Series - கூட்டு/பெருக்குத் தொடர், விடுபட்ட எண்)"},{"id":"vid_tnpsc_g2_d15_3","title":"TNPSC General Studies Day 15 High-Scoring Topics","tamilTitle":"பொது அறிவு நாள் 15 முக்கிய வினாக்கள்","youtubeVideoId":"0TgLtF3PMOc","channelName":"@aishleetechnology","durationMinutes":20,"type":"pyq","summary":"Unit 9: ஊரக நலன்சார் திட்டங்கள், வறுமை, தமிழ்நாட்டின் மனிதவள மேம்பாட்டுக் குறியீடுகள் (HDI)"}]'::jsonb, '[{"id":"note_tnpsc_g2_d15_admin","title":"TNPSC Group 2 Core High-Yield Deck (Day 15)","tamilTitle":"பாடக் குறிப்புகள் மற்றும் முக்கிய வினாக்கள்","type":"admin_core_ai","content":"Official Syllabus Review for Day 15. Tamil: அலகு VII: தமிழ்ச் சான்றோர் (பாரதிதாசன், டி.கே.சி, குன்றக்குடி, கண்ணதாசன், காயிதே மில்லத்) & பொருள் தரும் ஓரெழுத்து. Maths: எண் வரிசை (Number Series - கூட்டு/பெருக்குத் தொடர், விடுபட்ட எண்). GS: Unit 9: ஊரக நலன்சார் திட்டங்கள், வறுமை, தமிழ்நாட்டின் மனிதவள மேம்பாட்டுக் குறியீடுகள் (HDI).","formulasOrKeyRules":["TNPSC Target 185+ / 200 Questions","Zero Negative Marking Advantage","Daily Active Recall Active"],"examTrapsToAvoid":["Carefully check \"பொருந்தாதது எது\"","Do not misread similar Tamil words","Avoid calculation slips in algebra"]},{"id":"note_tnpsc_g2_d15_exam","title":"Day 15 Exam Tips & Memory Flashcards","tamilTitle":"நினைவுப் பலகைகள் மற்றும் குறுக்குவழி அட்டவணை","type":"admin_exam_ai","content":"Detailed memory aids and chronological timelines for Day 15.","formulasOrKeyRules":["5-Minute active recall every 45 mins","Night error log remediation"]}]'::jsonb, '{"testId":"test_tnpsc_g2_d15","title":"TNPSC Group 2 Daily Speed CBT Drill (Day 15)","tamilTitle":"நாள் 15 இணையவழி மாதிரித் தேர்வு (25 வினாக்கள்)","totalQuestions":25,"durationMinutes":25,"passingScore":20,"questions":[{"id":"q_g2_d15_1","question":"Sample Assessment for Day 15: Master Question 1 covering Tamil and GS.","questionTamil":"நாள் 15 பாடப்பகுதி மாதிரி வினா 1: பாடத்திட்ட அடிப்படையிலான தேர்வு.","options":{"A":"Option A (சரியான விடை)","B":"Option B","C":"Option C","D":"Option D"},"correctOption":"A","explanation":"Detailed explanation based on TNPSC syllabus standard."}]}'::jsonb, '{"asanaName":"Surya Namaskar & Nadi Shodhana Pranayama","tamilName":"சூரிய நமஸ்காரம் & நாடி சுத்தி பிராணாயாமம்","durationMinutes":15,"benefits":"Enhances neuro-cerebral oxygenation, sharpens memory retention and calms exam anxiety.","brainBoosterTask":"Solve 10 mental math calculation sprints without paper or pen in under 3 minutes."}'::jsonb
