) VALUES (
    'tnpsc-group2', 'TNPSC Group 2 & 2A — 25-Day Centum Ranker Fast-Track', 16, 3, 'Day 16',
    false, 'General Tamil & General Studies', 'TNPSC', 'Phase 2: Core Scoring Surge', 'அலகு VII: தாரா பாரதி, வேலுநாச்சியார், பட்டுக்கோட்டை, முடியரசன், தமிழ் ஒளி, உருத்திரங்கண்ணனார், கி.வா.ஜ, நாமக்கல் கவிஞர் | Aptitude & Mental Ability: சுருக்குதல், சதவீதம், மீ.பொ.கா, பகடை அதிவேக மாதிரித் தேர்வு',
    'அலகு VII: தாரா பாரதி, வேலுநாச்சியார், பட்டுக்கோட்டை, முடியரசன், தமிழ் ஒளி, உருத்திரங்கண்ணனார், கி.வா.ஜ, நாமக்கல் கவிஞர்', 'TNPSC-G2-D16', 135, 150,
    '[{"id":"vid_tnpsc_g2_d16_1","title":"TNPSC General Tamil Day 16 Masterclass","tamilTitle":"பொதுத்தமிழ் நாள் 16 முழு விளக்கம்","youtubeVideoId":"EpdTHQ0s6oM","channelName":"@aishleetechnology","durationMinutes":25,"type":"foundation","summary":"அலகு VII: தாரா பாரதி, வேலுநாச்சியார், பட்டுக்கோட்டை, முடியரசன், தமிழ் ஒளி, உருத்திரங்கண்ணனார், கி.வா.ஜ, நாமக்கல் கவிஞர்"},{"id":"vid_tnpsc_g2_d16_2","title":"TNPSC Aptitude 25/25 Day 16 Speed Shortcuts","tamilTitle":"கணிதம் & திறனறிவு நாள் 16 குறுக்குவழிகள்","youtubeVideoId":"aishlee_tnpsc_aptitude_1","channelName":"@aishleetechnology","durationMinutes":20,"type":"derivation","summary":"Aptitude & Mental Ability: சுருக்குதல், சதவீதம், மீ.பொ.கா, பகடை அதிவேக மாதிரித் தேர்வு"},{"id":"vid_tnpsc_g2_d16_3","title":"TNPSC General Studies Day 16 High-Scoring Topics","tamilTitle":"பொது அறிவு நாள் 16 முக்கிய வினாக்கள்","youtubeVideoId":"0TgLtF3PMOc","channelName":"@aishleetechnology","durationMinutes":20,"type":"pyq","summary":"Unit 9: சமூக மறுமலர்ச்சி இயக்கங்கள் பங்களிப்பு, தமிழ்நாடு 69% இடஒதுக்கீட்டுக் கொள்கை நியாயங்கள்"}]'::jsonb, '[{"id":"note_tnpsc_g2_d16_admin","title":"TNPSC Group 2 Core High-Yield Deck (Day 16)","tamilTitle":"பாடக் குறிப்புகள் மற்றும் முக்கிய வினாக்கள்","type":"admin_core_ai","content":"Official Syllabus Review for Day 16. Tamil: அலகு VII: தாரா பாரதி, வேலுநாச்சியார், பட்டுக்கோட்டை, முடியரசன், தமிழ் ஒளி, உருத்திரங்கண்ணனார், கி.வா.ஜ, நாமக்கல் கவிஞர். Maths: Aptitude & Mental Ability: சுருக்குதல், சதவீதம், மீ.பொ.கா, பகடை அதிவேக மாதிரித் தேர்வு. GS: Unit 9: சமூக மறுமலர்ச்சி இயக்கங்கள் பங்களிப்பு, தமிழ்நாடு 69% இடஒதுக்கீட்டுக் கொள்கை நியாயங்கள்.","formulasOrKeyRules":["TNPSC Target 185+ / 200 Questions","Zero Negative Marking Advantage","Daily Active Recall Active"],"examTrapsToAvoid":["Carefully check \"பொருந்தாதது எது\"","Do not misread similar Tamil words","Avoid calculation slips in algebra"]},{"id":"note_tnpsc_g2_d16_exam","title":"Day 16 Exam Tips & Memory Flashcards","tamilTitle":"நினைவுப் பலகைகள் மற்றும் குறுக்குவழி அட்டவணை","type":"admin_exam_ai","content":"Detailed memory aids and chronological timelines for Day 16.","formulasOrKeyRules":["5-Minute active recall every 45 mins","Night error log remediation"]}]'::jsonb, '{"testId":"test_tnpsc_g2_d16","title":"TNPSC Group 2 Daily Speed CBT Drill (Day 16)","tamilTitle":"நாள் 16 இணையவழி மாதிரித் தேர்வு (25 வினாக்கள்)","totalQuestions":25,"durationMinutes":25,"passingScore":20,"questions":[{"id":"q_g2_d16_1","question":"Sample Assessment for Day 16: Master Question 1 covering Tamil and GS.","questionTamil":"நாள் 16 பாடப்பகுதி மாதிரி வினா 1: பாடத்திட்ட அடிப்படையிலான தேர்வு.","options":{"A":"Option A (சரியான விடை)","B":"Option B","C":"Option C","D":"Option D"},"correctOption":"A","explanation":"Detailed explanation based on TNPSC syllabus standard."}]}'::jsonb, '{"asanaName":"Surya Namaskar & Nadi Shodhana Pranayama","tamilName":"சூரிய நமஸ்காரம் & நாடி சுத்தி பிராணாயாமம்","durationMinutes":15,"benefits":"Enhances neuro-cerebral oxygenation, sharpens memory retention and calms exam anxiety.","brainBoosterTask":"Solve 10 mental math calculation sprints without paper or pen in under 3 minutes."}'::jsonb
) ON CONFLICT (course_id, day_number) DO UPDATE SET
