) VALUES (
    'tnpsc-group2', 'TNPSC Group 2 & 2A — 25-Day Centum Ranker Fast-Track', 17, 3, 'Day 17',
    false, 'General Tamil & General Studies', 'TNPSC', 'Phase 3: Total Syllabus Coverage', 'அலகு III: எழுதும் திறன் (சொற்களை ஒழுங்குபடுத்துதல், செய்வினை/செயப்பாட்டு வினை, தன்வினை/பிறவினை, ஒருமை/பன்மை) | Aptitude Sprint: விகிதம், தனிவட்டி, கூட்டுவட்டி, எண் எழுத்துக் காரணவியல் 30 வினாக்கள்',
    'அலகு III: எழுதும் திறன் (சொற்களை ஒழுங்குபடுத்துதல், செய்வினை/செயப்பாட்டு வினை, தன்வினை/பிறவினை, ஒருமை/பன்மை)', 'TNPSC-G2-D17', 135, 150,
    '[{"id":"vid_tnpsc_g2_d17_1","title":"TNPSC General Tamil Day 17 Masterclass","tamilTitle":"பொதுத்தமிழ் நாள் 17 முழு விளக்கம்","youtubeVideoId":"EpdTHQ0s6oM","channelName":"@aishleetechnology","durationMinutes":25,"type":"foundation","summary":"அலகு III: எழுதும் திறன் (சொற்களை ஒழுங்குபடுத்துதல், செய்வினை/செயப்பாட்டு வினை, தன்வினை/பிறவினை, ஒருமை/பன்மை)"},{"id":"vid_tnpsc_g2_d17_2","title":"TNPSC Aptitude 25/25 Day 17 Speed Shortcuts","tamilTitle":"கணிதம் & திறனறிவு நாள் 17 குறுக்குவழிகள்","youtubeVideoId":"aishlee_tnpsc_aptitude_1","channelName":"@aishleetechnology","durationMinutes":20,"type":"derivation","summary":"Aptitude Sprint: விகிதம், தனிவட்டி, கூட்டுவட்டி, எண் எழுத்துக் காரணவியல் 30 வினாக்கள்"},{"id":"vid_tnpsc_g2_d17_3","title":"TNPSC General Studies Day 17 High-Scoring Topics","tamilTitle":"பொது அறிவு நாள் 17 முக்கிய வினாக்கள்","youtubeVideoId":"0TgLtF3PMOc","channelName":"@aishleetechnology","durationMinutes":20,"type":"pyq","summary":"Unit 9: தமிழ்நாட்டின் பொருளாதாரப் போக்குகள், சமூகநீதி, கல்வி, நல்வாழ்வு முறைமைகள் & மின்னாளுகை (e-Governance)"}]'::jsonb, '[{"id":"note_tnpsc_g2_d17_admin","title":"TNPSC Group 2 Core High-Yield Deck (Day 17)","tamilTitle":"பாடக் குறிப்புகள் மற்றும் முக்கிய வினாக்கள்","type":"admin_core_ai","content":"Official Syllabus Review for Day 17. Tamil: அலகு III: எழுதும் திறன் (சொற்களை ஒழுங்குபடுத்துதல், செய்வினை/செயப்பாட்டு வினை, தன்வினை/பிறவினை, ஒருமை/பன்மை). Maths: Aptitude Sprint: விகிதம், தனிவட்டி, கூட்டுவட்டி, எண் எழுத்துக் காரணவியல் 30 வினாக்கள். GS: Unit 9: தமிழ்நாட்டின் பொருளாதாரப் போக்குகள், சமூகநீதி, கல்வி, நல்வாழ்வு முறைமைகள் & மின்னாளுகை (e-Governance).","formulasOrKeyRules":["TNPSC Target 185+ / 200 Questions","Zero Negative Marking Advantage","Daily Active Recall Active"],"examTrapsToAvoid":["Carefully check \"பொருந்தாதது எது\"","Do not misread similar Tamil words","Avoid calculation slips in algebra"]},{"id":"note_tnpsc_g2_d17_exam","title":"Day 17 Exam Tips & Memory Flashcards","tamilTitle":"நினைவுப் பலகைகள் மற்றும் குறுக்குவழி அட்டவணை","type":"admin_exam_ai","content":"Detailed memory aids and chronological timelines for Day 17.","formulasOrKeyRules":["5-Minute active recall every 45 mins","Night error log remediation"]}]'::jsonb, '{"testId":"test_tnpsc_g2_d17","title":"TNPSC Group 2 Daily Speed CBT Drill (Day 17)","tamilTitle":"நாள் 17 இணையவழி மாதிரித் தேர்வு (25 வினாக்கள்)","totalQuestions":25,"durationMinutes":25,"passingScore":20,"questions":[{"id":"q_g2_d17_1","question":"Sample Assessment for Day 17: Master Question 1 covering Tamil and GS.","questionTamil":"நாள் 17 பாடப்பகுதி மாதிரி வினா 1: பாடத்திட்ட அடிப்படையிலான தேர்வு.","options":{"A":"Option A (சரியான விடை)","B":"Option B","C":"Option C","D":"Option D"},"correctOption":"A","explanation":"Detailed explanation based on TNPSC syllabus standard."}]}'::jsonb, '{"asanaName":"Surya Namaskar & Nadi Shodhana Pranayama","tamilName":"சூரிய நமஸ்காரம் & நாடி சுத்தி பிராணாயாமம்","durationMinutes":15,"benefits":"Enhances neuro-cerebral oxygenation, sharpens memory retention and calms exam anxiety.","brainBoosterTask":"Solve 10 mental math calculation sprints without paper or pen in under 3 minutes."}'::jsonb
