) VALUES (
    'tnpsc-group2', 'TNPSC Group 2 & 2A — 25-Day Centum Ranker Fast-Track', 19, 3, 'Day 19',
    false, 'General Tamil & General Studies', 'TNPSC', 'Phase 3: Total Syllabus Coverage', 'அலகு IV: பல்துறை கலைச் சொற்கள் (அறிவியல், கல்வி, மருத்துவம், சட்டம்)  | Reasoning Sprint: புதிர்கள், பகடை, காட்சிக் காரணவியல் மற்றும் எண் வரிசை அதிவேக பயிற்சி',
    'அலகு IV: பல்துறை கலைச் சொற்கள் (அறிவியல், கல்வி, மருத்துவம், சட்டம்) & அலகு VI: எளிய மொழிபெயர்ப்பு', 'TNPSC-G2-D19', 135, 150,
    '[{"id":"vid_tnpsc_g2_d19_1","title":"TNPSC General Tamil Day 19 Masterclass","tamilTitle":"பொதுத்தமிழ் நாள் 19 முழு விளக்கம்","youtubeVideoId":"EpdTHQ0s6oM","channelName":"@aishleetechnology","durationMinutes":25,"type":"foundation","summary":"அலகு IV: பல்துறை கலைச் சொற்கள் (அறிவியல், கல்வி, மருத்துவம், சட்டம்) & அலகு VI: எளிய மொழிபெயர்ப்பு"},{"id":"vid_tnpsc_g2_d19_2","title":"TNPSC Aptitude 25/25 Day 19 Speed Shortcuts","tamilTitle":"கணிதம் & திறனறிவு நாள் 19 குறுக்குவழிகள்","youtubeVideoId":"aishlee_tnpsc_aptitude_1","channelName":"@aishleetechnology","durationMinutes":20,"type":"derivation","summary":"Reasoning Sprint: புதிர்கள், பகடை, காட்சிக் காரணவியல் மற்றும் எண் வரிசை அதிவேக பயிற்சி"},{"id":"vid_tnpsc_g2_d19_3","title":"TNPSC General Studies Day 19 High-Scoring Topics","tamilTitle":"பொது அறிவு நாள் 19 முக்கிய வினாக்கள்","youtubeVideoId":"0TgLtF3PMOc","channelName":"@aishleetechnology","durationMinutes":20,"type":"pyq","summary":"Unit 3: சிந்து சமவெளி, குப்தர்கள், தில்லி சுல்தான்கள், முகலாயர்கள், மராத்தியர்கள், விஜயநகரம், தென்னிந்திய வரலாறு"}]'::jsonb, '[{"id":"note_tnpsc_g2_d19_admin","title":"TNPSC Group 2 Core High-Yield Deck (Day 19)","tamilTitle":"பாடக் குறிப்புகள் மற்றும் முக்கிய வினாக்கள்","type":"admin_core_ai","content":"Official Syllabus Review for Day 19. Tamil: அலகு IV: பல்துறை கலைச் சொற்கள் (அறிவியல், கல்வி, மருத்துவம், சட்டம்) & அலகு VI: எளிய மொழிபெயர்ப்பு. Maths: Reasoning Sprint: புதிர்கள், பகடை, காட்சிக் காரணவியல் மற்றும் எண் வரிசை அதிவேக பயிற்சி. GS: Unit 3: சிந்து சமவெளி, குப்தர்கள், தில்லி சுல்தான்கள், முகலாயர்கள், மராத்தியர்கள், விஜயநகரம், தென்னிந்திய வரலாறு.","formulasOrKeyRules":["TNPSC Target 185+ / 200 Questions","Zero Negative Marking Advantage","Daily Active Recall Active"],"examTrapsToAvoid":["Carefully check \"பொருந்தாதது எது\"","Do not misread similar Tamil words","Avoid calculation slips in algebra"]},{"id":"note_tnpsc_g2_d19_exam","title":"Day 19 Exam Tips & Memory Flashcards","tamilTitle":"நினைவுப் பலகைகள் மற்றும் குறுக்குவழி அட்டவணை","type":"admin_exam_ai","content":"Detailed memory aids and chronological timelines for Day 19.","formulasOrKeyRules":["5-Minute active recall every 45 mins","Night error log remediation"]}]'::jsonb, '{"testId":"test_tnpsc_g2_d19","title":"TNPSC Group 2 Daily Speed CBT Drill (Day 19)","tamilTitle":"நாள் 19 இணையவழி மாதிரித் தேர்வு (25 வினாக்கள்)","totalQuestions":25,"durationMinutes":25,"passingScore":20,"questions":[{"id":"q_g2_d19_1","question":"Sample Assessment for Day 19: Master Question 1 covering Tamil and GS.","questionTamil":"நாள் 19 பாடப்பகுதி மாதிரி வினா 1: பாடத்திட்ட அடிப்படையிலான தேர்வு.","options":{"A":"Option A (சரியான விடை)","B":"Option B","C":"Option C","D":"Option D"},"correctOption":"A","explanation":"Detailed explanation based on TNPSC syllabus standard."}]}'::jsonb, '{"asanaName":"Surya Namaskar & Nadi Shodhana Pranayama","tamilName":"சூரிய நமஸ்காரம் & நாடி சுத்தி பிராணாயாமம்","durationMinutes":15,"benefits":"Enhances neuro-cerebral oxygenation, sharpens memory retention and calms exam anxiety.","brainBoosterTask":"Solve 10 mental math calculation sprints without paper or pen in under 3 minutes."}'::jsonb
