    '[{"id":"vid_tnpsc_g2_d20_1","title":"TNPSC General Tamil Day 20 Masterclass","tamilTitle":"பொதுத்தமிழ் நாள் 20 முழு விளக்கம்","youtubeVideoId":"EpdTHQ0s6oM","channelName":"@aishleetechnology","durationMinutes":25,"type":"foundation","summary":"அலகு V: வாசித்தல் புரிந்து கொள்ளும் திறன் (பத்தி வினாக்கள், தலையங்கம், உவமைத் தொடர், மரபுத் தொடர், பழமொழிகள்)"},{"id":"vid_tnpsc_g2_d20_2","title":"TNPSC Aptitude 25/25 Day 20 Speed Shortcuts","tamilTitle":"கணிதம் & திறனறிவு நாள் 20 குறுக்குவழிகள்","youtubeVideoId":"aishlee_tnpsc_aptitude_1","channelName":"@aishleetechnology","durationMinutes":20,"type":"derivation","summary":"Aptitude 25/25 Mock Speed Drill: அதிகாரப்பூர்வ TNPSC கணித மாதிரித் தேர்வு (20 நிமிடங்கள்)"},{"id":"vid_tnpsc_g2_d20_3","title":"TNPSC General Studies Day 20 High-Scoring Topics","tamilTitle":"பொது அறிவு நாள் 20 முக்கிய வினாக்கள்","youtubeVideoId":"0TgLtF3PMOc","channelName":"@aishleetechnology","durationMinutes":20,"type":"pyq","summary":"Unit 3: இந்திய தேசிய இயக்கம், தேசிய மறுமலர்ச்சி, INC, காந்தி, நேரு, அம்பேத்கர், சுபாஷ் சந்திர போஸ், பகத்சிங்"}]'::jsonb, '[{"id":"note_tnpsc_g2_d20_admin","title":"TNPSC Group 2 Core High-Yield Deck (Day 20)","tamilTitle":"பாடக் குறிப்புகள் மற்றும் முக்கிய வினாக்கள்","type":"admin_core_ai","content":"Official Syllabus Review for Day 20. Tamil: அலகு V: வாசித்தல் புரிந்து கொள்ளும் திறன் (பத்தி வினாக்கள், தலையங்கம், உவமைத் தொடர், மரபுத் தொடர், பழமொழிகள்). Maths: Aptitude 25/25 Mock Speed Drill: அதிகாரப்பூர்வ TNPSC கணித மாதிரித் தேர்வு (20 நிமிடங்கள்). GS: Unit 3: இந்திய தேசிய இயக்கம், தேசிய மறுமலர்ச்சி, INC, காந்தி, நேரு, அம்பேத்கர், சுபாஷ் சந்திர போஸ், பகத்சிங்.","formulasOrKeyRules":["TNPSC Target 185+ / 200 Questions","Zero Negative Marking Advantage","Daily Active Recall Active"],"examTrapsToAvoid":["Carefully check \"பொருந்தாதது எது\"","Do not misread similar Tamil words","Avoid calculation slips in algebra"]},{"id":"note_tnpsc_g2_d20_exam","title":"Day 20 Exam Tips & Memory Flashcards","tamilTitle":"நினைவுப் பலகைகள் மற்றும் குறுக்குவழி அட்டவணை","type":"admin_exam_ai","content":"Detailed memory aids and chronological timelines for Day 20.","formulasOrKeyRules":["5-Minute active recall every 45 mins","Night error log remediation"]}]'::jsonb, '{"testId":"test_tnpsc_g2_d20","title":"TNPSC Group 2 Daily Speed CBT Drill (Day 20)","tamilTitle":"நாள் 20 இணையவழி மாதிரித் தேர்வு (25 வினாக்கள்)","totalQuestions":25,"durationMinutes":25,"passingScore":20,"questions":[{"id":"q_g2_d20_1","question":"Sample Assessment for Day 20: Master Question 1 covering Tamil and GS.","questionTamil":"நாள் 20 பாடப்பகுதி மாதிரி வினா 1: பாடத்திட்ட அடிப்படையிலான தேர்வு.","options":{"A":"Option A (சரியான விடை)","B":"Option B","C":"Option C","D":"Option D"},"correctOption":"A","explanation":"Detailed explanation based on TNPSC syllabus standard."}]}'::jsonb, '{"asanaName":"Surya Namaskar & Nadi Shodhana Pranayama","tamilName":"சூரிய நமஸ்காரம் & நாடி சுத்தி பிராணாயாமம்","durationMinutes":15,"benefits":"Enhances neuro-cerebral oxygenation, sharpens memory retention and calms exam anxiety.","brainBoosterTask":"Solve 10 mental math calculation sprints without paper or pen in under 3 minutes."}'::jsonb
